	/** Все словари по идентификаторам локалей. */
	const DICTIONARIES = { ru, en, zh }

	/**
	 * Переводчик по умолчанию: русский словарь.
	 *
	 * Объявлен здесь, а не в потребителях, потому что все модули сборки попадают в
	 * один общий scope: два объявления с этим именем роняли бы весь бандл.
	 * Нужен там, где настоящий `t` от рантайма ещё не пришёл — вызов из теста или
	 * старая ревизия слота.
	 *
	 * @type {(key: string, vars?: Record<string, unknown>) => string}
	 */
	const defaultTranslate = (key, vars) => {
	  const text = ru[key]
	  if (typeof text !== 'string') return key
	  if (vars === undefined || vars === null) return text
	  return text.replace(/\{(\w+)\}/g, (match, name) => {
	    const value = vars[name]
	    return value === undefined || value === null ? match : String(value)
	  })
	}

	/**
	 * Собирает переводчик поверх одного словаря.
	 *
	 * Подстановка `{name}` сделана вручную, а не регуляркой по строке: так
	 * значение, содержащее фигурные скобки, не испортит разметку шаблона. Отсутствие
	 * значения в `vars` оставляет плейсхолдер как есть — такой текст заметнее, чем
	 * пустая строка, и виден в тестах.
	 *
	 * @param {Record<string, string>} [dict] - словарь (по умолчанию русский).
	 * @returns {(key: string, vars?: Record<string, unknown>) => string} переводчик.
	 */
	function createTranslate(dict = ru) {
	  return (key, vars) => {
	    const text = dict[key]
	    if (typeof text !== 'string') return key
	    if (vars === undefined || vars === null) return text
	    return text.replace(/\{(\w+)\}/g, (match, name) => {
	      const value = vars[name]
	      return value === undefined || value === null ? match : String(value)
	    })
	  }
	}

	// ── src/client/api.js ───────────────────────────────────────────
	// Связь клиентской половины с host-маршрутами плагина.
	//
	// Своего RPC-канала у пакета нет: host-половина публикует обычные HTTP-маршруты
	// под префиксом `/voice-eternia`, а GUI открыт с того же origin, поэтому ходим
	// обычным fetch. Ключи API на хосте остаются на хосте — сюда приходит только
	// распознанный текст.

	/** Префикс маршрутов пакета. */
	const API_PREFIX = '/voice-eternia'

	/**
	 * Разбирает ответ маршрута.
	 *
	 * @param {Response} response - ответ fetch.
	 * @returns {Promise<object>} разобранное тело либо описание ошибки.
	 */
	async function parse(response) {
	  let payload
	  try {
	    payload = await response.json()
	  } catch {
	    return { ok: false, error: { code: 'bad-response', message: `Сервер ответил ${response.status}` } }
	  }
	  if (payload !== null && typeof payload === 'object') return payload
	  return { ok: false, error: { code: 'bad-response', message: 'Пустой ответ сервера.' } }
	}

	/**
	 * Отправляет POST без тела, ожидая ответ маршрута захвата.
	 *
	 * @param {string} url - адрес маршрута.
	 * @param {object} body - тело запроса.
	 * @returns {Promise<object>} разобранный ответ.
	 */
	async function post(url, body) {
	  try {
	    const response = await fetch(url, {
	      method: 'POST',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify(body),
	    })
	    return await parse(response)
	  } catch {
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Просит хост начать запись микрофона.
	 *
	 * Запись ведёт хост, а не страница: в окне Electron `getUserMedia` отказывает
	 * молча, потому что подписанная оболочка не пропускает разрешение `media`.
	 * На хосте запись делает внешняя программа, и браузер в процессе не участвует.
	 *
	 * @returns {Promise<{ ok: boolean, device?: string, maxSeconds?: number, error?: object }>}
	 */
	async function startRecording() {
	  return post(`${API_PREFIX}/record/start`, {})
	}

	/**
	 * Останавливает запись и забирает WAV.
	 *
	 * @returns {Promise<{ ok: boolean, audioBase64?: string, bytes?: number, error?: object }>}
	 */
	async function stopRecording() {
	  return post(`${API_PREFIX}/record/stop`, {})
	}

	/**
	 * Отменяет запись, ничего не возвращая.
	 *
	 * @returns {Promise<{ ok: boolean }>}
	 */
	async function cancelRecording() {
	  return post(`${API_PREFIX}/record/cancel`, {})
	}

	/**
	 * Читает состояние записи: идёт ли она и каков уровень сигнала.
	 *
	 * @returns {Promise<{ ok: boolean, value?: { recording: boolean, level: number, seconds: number }, error?: object }>}
	 */
	async function recordingStatus() {
	  try {
	    const response = await fetch(`${API_PREFIX}/record/status`, { method: 'GET' })
	    return await parse(response)
	  } catch {
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Читает настройки плагина, заданные в карточке.
	 *
	 * Клиенту нужны только те, что меняют поведение кнопки: показывать ли запасной
	 * путь через браузер и вставлять ли результат автоматически. Остальное
	 * (модель, промпт, микрофон) читает хост — он же делает запрос к моделям.
	 *
	 * @returns {Promise<object|null>} настройки либо null при недоступности.
	 */
	async function readConfig() {
	  try {
	    const response = await fetch(`${API_PREFIX}/config`, { method: 'GET' })
	    const payload = await parse(response)
	    if (payload.ok !== true || payload.value === null || typeof payload.value !== 'object') return null
	    return payload.value
	  } catch {
	    return null
	  }
	}

	/**
	 * Сохраняет настройки плагина.
	 *
	 * Хост принимает вложенные группы и раскладывает их в свой запасной файл, а
	 * `readSettings` перечитывает его на каждый запрос — поэтому правка видна
	 * сразу, без перезапуска DSH.
	 *
	 * @param {object} settings - настройки целиком.
	 * @returns {Promise<{ ok: boolean, value?: object, error?: object }>}
	 */
	async function writeConfig(settings) {
	  try {
	    const response = await fetch(`${API_PREFIX}/config`, {
	      method: 'PUT',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify(settings),
	    })
	    return await parse(response)
	  } catch {
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Отправляет аудио на распознавание.
	 *
	 * @param {object} options - параметры.
	 * @param {string} options.audioBase64 - WAV в base64.
	 * @param {AbortSignal} [options.signal] - отмена.
	 * @returns {Promise<{ ok: boolean, text?: string, empty?: boolean, tookMs?: number, error?: object }>} результат.
	 */
	async function transcribe({ audioBase64, signal }) {
	  try {
	    const response = await fetch(`${API_PREFIX}/transcribe`, {
	      method: 'POST',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify({ audioBase64 }),
	      signal,
	    })
	    return await parse(response)
	  } catch (failure) {
	    if (failure instanceof Error && failure.name === 'AbortError') {
	      return { ok: false, error: { code: 'aborted', message: 'Распознавание отменено.' } }
	    }
	    return { ok: false, error: { code: 'network', message: 'Хост недоступен.' } }
	  }
	}

	/**
	 * Просит отполировать текст.
	 *
	 * Полировка — улучшение, а не обязательный шаг: при любой ошибке хост вернёт
	 * исходный текст, поэтому вызывающий код обязан смотреть на поле `polished`.
	 *
	 * @param {object} options - параметры.
	 * @param {string} options.text - сырой текст.
	 * @param {AbortSignal} [options.signal] - отмена.
	 * @returns {Promise<{ ok: boolean, text: string, polished?: boolean }>} результат.
	 */
	async function polish({ text, signal }) {
	  try {
	    const response = await fetch(`${API_PREFIX}/polish`, {
	      method: 'POST',
	      headers: { 'Content-Type': 'application/json' },
	      body: JSON.stringify({ text }),
	      signal,
	    })
	    const payload = await parse(response)
	    if (payload.ok === false) return { ok: false, text }
	    return { ok: true, text: typeof payload.text === 'string' ? payload.text : text, polished: payload.polished === true }
	  } catch {
	    return { ok: false, text }
	  }
	}

	/**
	 * Спрашивает у хоста адрес того же GUI для обычного браузера.
	 *
	 * Нужен, когда микрофон заблокирован оболочкой Electron: браузер по этому
	 * адресу показывает свой запрос доступа, и диктовка работает. Пустой `webUrl`
	 * означает «порт неизвестен» — тогда кнопку открытия не показываем, чтобы не
	 * вести пользователя по нерабочей ссылке.
	 *
	 * @returns {Promise<{ webUrl: string, port: number | null } | null>} адрес либо null.
	 */
	async function readEnvironment() {
	  try {
	    const response = await fetch(`${API_PREFIX}/env`, { method: 'GET' })
	    const payload = await parse(response)
	    if (payload.ok !== true || payload.value === null || typeof payload.value !== 'object') return null
	    return {
	      webUrl: typeof payload.value.webUrl === 'string' ? payload.value.webUrl : '',
	      port: typeof payload.value.port === 'number' ? payload.value.port : null,
	    }
	  } catch {
	    return null
	  }
	}

	/**
	 * Читает список моделей, настроенных в самом DSH.
	 *
	 * Зачем это нужно. Поле «модель» текстом — плохая просьба: `id` провайдера и
	 * точное имя модели человек помнить не обязан, а одна опечатка даёт молчаливый
	 * отказ при первой же записи. Хост читает список из профиля DSH — того самого,
	 * что виден в разделе «Модели», — и отдаёт его сюда для выпадающего списка.
	 *
	 * @returns {Promise<Array<object>|null>} модели либо null при недоступности.
	 */
	async function readModels() {
	  try {
	    const response = await fetch(`${API_PREFIX}/models`, { method: 'GET' })
	    const payload = await parse(response)
	    return payload.ok === true && Array.isArray(payload.models) ? payload.models : null
	  } catch {
	    return null
	  }
	}

	/**
	 * Читает имена записей с ключами доступа.
	 *
	 * Сами ключи сюда не приходят и прийти не могут: хост отдаёт только имена.
	 * Это и есть смысл списка — секрет вводят в хранилище DSH, а плагин лишь
	 * ссылается на запись по имени.
	 *
	 * @returns {Promise<Array<object>|null>} записи либо null при недоступности.
	 */
	async function readCredentials() {
	  try {
	    const response = await fetch(`${API_PREFIX}/credentials`, { method: 'GET' })
	    const payload = await parse(response)
	    return payload.ok === true && Array.isArray(payload.credentials) ? payload.credentials : null
	  } catch {
	    return null
	  }
	}


	// ── src/client/recorder.js ──────────────────────────────────────
	// Управление записью микрофона на стороне клиента.
	//
	// Запись ведёт ХОСТ, а не страница. Причина не в плагине: окно DSH Desktop —
	// это Electron, и подписанный `app.asar` пропускает через
	// `canGrantWindowPermission` только `clipboard-sanitized-write` и
	// `notifications`. Разрешения `media` в белом списке нет, поэтому `getUserMedia`
	// отказывает молча, без системного диалога, и никакой код плагина это не
	// обходит.
	//
	// Белый список относится к ОКНУ, а не к процессу хоста: хост — обычный Node,
	// где микрофон пишет внешняя программа (см. `src/capture.js`). Поэтому здесь
	// нет ни `getUserMedia`, ни `MediaRecorder`, ни пересэмплирования через Web
	// Audio — всё это браузерные обходные пути, которые в приложении не работают.
	// Клиент только спрашивает хоста: начать, остановить, где мы сейчас.
	//
	// Пересэмплирование тоже не нужно: хост пишет сразу 16 кГц mono — ровно тот
	// формат, который ждут облачные модели.



	/** Частота, которую ждут модели распознавания. */
	const TARGET_SAMPLE_RATE = 16000

	/** Максимальная длительность одной записи, секунды (защита от забытой записи). */
	const MAX_RECORD_SECONDS = 120

	/** Класс отказа, понятный человеку. */
	class RecorderError extends Error {
	  /**
	   * @param {string} kind - категория отказа.
	   * @param {string} message - текст для пользователя.
	   */
	  constructor(kind, message) {
	    super(message)
	    this.name = 'RecorderError'
	    this.kind = kind
	  }
	}

	/**
	 * Признак оболочки Electron.
	 *
	 * Нужен только для выбора текста отказа: в приложении микрофон берёт хост, в
	 * обычном браузере — по-прежнему `getUserMedia`, и там отказ означает совсем
	 * другое.
	 *
	 * @returns {boolean} верно ли, что страница открыта в Electron.
	 */
	function isDesktopShell() {
	  return typeof navigator !== 'undefined' && /electron/i.test(navigator.userAgent ?? '')
	}

	/**
	 * Проверяет, можно ли вести запись в этой среде.
	 *
	 * Раньше здесь проверялся `navigator.mediaDevices`. Теперь запись идёт через
	 * хост, поэтому проверять нечего: если хост на месте — пишем, если нет —
	 * отказ придёт от маршрута с понятным текстом. Оставляем функцию, потому что
	 * вызывающий код ждёт её ответа, и она же объясняет пользователю случай, когда
	 * плагин открыли вообще без хоста.
	 *
	 * @returns {{ available: boolean, reason: string }} доступность и причина.
	 */
	function probeSupport() {
	  if (typeof fetch !== 'function') {
	    return { available: false, reason: 'offline' }
	  }
	  return { available: true, reason: '' }
	}

	/**
	 * Читает имя ошибки, не полагаясь на `instanceof`.
	 *
	 * `instanceof Error` ненадёжен сразу по двум причинам: ошибка может прийти из
	 * другого realm (iframe, песочница), где прототип другой. Читаем поле `name`
	 * напрямую.
	 *
	 * @param {unknown} failure - произвольное значение.
	 * @returns {{ name: string, message: string }} имя и текст.
	 */
	function describeFailure(failure) {
	  if (failure === null || typeof failure !== 'object') {
	    return { name: '', message: String(failure) }
	  }
	  const name = typeof failure.name === 'string' ? failure.name : ''
	  const message = typeof failure.message === 'string' ? failure.message : ''
	  return { name, message }
	}

	/**
	 * Переводит отказ в текст для пользователя.
	 *
	 * Коды приходят с хоста и уже человекочитаемы, поэтому подробности оракула о
	 * них мы сохраняем, а код без разбора отдаём как есть. Подсказка зависит от
	 * среды: в браузере отказ почти всегда значит «пользователь закрыл диалог или
	 * запретил микрофон в настройках сайта», и это другой совет.
	 *
	 * @param {unknown} failure - отказ: `RecorderError` или ответ маршрута.
	 * @param {(key: string, vars?: object) => string} [t] - переводчик словаря.
	 * @returns {RecorderError} ошибка с категорией.
	 */
	function classifyFailure(failure, t = defaultTranslate) {
	  if (failure instanceof RecorderError) return failure
	  const { name, message } = describeFailure(failure)
	  const code = typeof failure?.error?.code === 'string' ? failure.error.code : ''
	  const detail = typeof failure?.error?.message === 'string' && failure.error.message !== ''
	    ? failure.error.message
	    : message

	  if (name === 'NotAllowedError' || name === 'SecurityError') {
	    return new RecorderError(
	      'denied',
	      t(isDesktopShell() ? 'error.deniedDesktop' : 'error.deniedSite'),
	    )
	  }
	  if (code === 'nodevice' || name === 'NotFoundError' || name === 'OverconstrainedError') {
	    return new RecorderError('nodevice', t('error.noDevice'))
	  }
	  if (code === 'busy' || name === 'NotReadableError') {
	    return new RecorderError('busy', t('error.busy'))
	  }
	  // Код от хоста уже содержит причину («На машине нет ffmpeg…»): переписывать
	  // его своим текстом значило бы потерять полезную подробность.
	  if (detail !== '') return new RecorderError(code === '' ? 'unknown' : code, detail)
	  return new RecorderError('unknown', t('error.unknown'))
	}

	/**
	 * Короткий путь для мест, где нужна только строка сообщения.
	 *
	 * @param {unknown} failure - отказ.
	 * @param {(key: string, vars?: object) => string} [t] - переводчик.
	 * @returns {string} текст для пользователя.
	 */
	function classifyFailureMessage(failure, t = defaultTranslate) {
	  return classifyFailure(failure, t).message
	}

	/**
	 * Кодирует сэмплы в WAV: 16 бит, mono, RIFF-заголовок 44 байта.
	 *
	 * Запись с микрофона приходит с хоста уже в WAV, поэтому функция нужна для
	 * синтетических сэмплов и для проверок формата; на пути диктовки её не
	 * вызывают.
	 *
	 * @param {Float32Array} samples - сэмплы в диапазоне [-1, 1].
	 * @returns {Uint8Array} готовый файл.
	 */
	function encodeWave(samples) {
	  const bytes = new Uint8Array(44 + samples.length * 2)
	  const view = new DataView(bytes.buffer)
	  const text = (at, value) => {
	    for (let i = 0; i < value.length; i += 1) bytes[at + i] = value.charCodeAt(i)
	  }
	  text(0, 'RIFF')
	  view.setUint32(4, bytes.length - 8, true)
	  text(8, 'WAVE')
	  text(12, 'fmt ')
	  view.setUint32(16, 16, true)
	  view.setUint16(20, 1, true) // PCM
	  view.setUint16(22, 1, true) // mono
	  view.setUint32(24, TARGET_SAMPLE_RATE, true)
	  view.setUint32(28, TARGET_SAMPLE_RATE * 2, true)
	  view.setUint16(32, 2, true)
	  view.setUint16(34, 16, true)
	  text(36, 'data')
	  view.setUint32(40, samples.length * 2, true)
	  for (let i = 0; i < samples.length; i += 1) {
	    // Ограничение асимметричное, как требует PCM16: −32768 влезает в знаковый
	    // 16-битный тип, а +32768 не влезает и стал бы −32768 — то есть тихий
	    // всплеск тихо превратился бы в резкий щелчок в начале сигнала.
	    const sample = samples[i]
	    const value = sample <= -1 ? -32768 : sample >= 1 ? 32767 : Math.round(sample * 32767)
	    view.setInt16(44 + i * 2, value, true)
	  }
	  return bytes
	}

	/**
	 * Переводит байты в base64 без `btoa` над большим массивом.
	 *
	 * @param {Uint8Array|Buffer} bytes - данные.
	 * @returns {string} base64.
	 */
	function toBase64(bytes) {
	  let binary = ''
	  const step = 0x8000
	  for (let i = 0; i < bytes.length; i += step) {
	    binary += String.fromCharCode(...bytes.subarray(i, Math.min(i + step, bytes.length)))
	  }
	  return btoa(binary)
	}

	/**
	 * Одна запись с микрофона.
	 *
	 * Жизненный цикл: `start()` → `stop()` → освобождение. Отмена, сбой и
	 * выгрузка плагина ведут в один и тот же `dispose()`, поэтому повторный вызов
	 * безопасен: освобождение обязано быть идемпотентным.
	 *
	 * Уровень сигнала приходит опросом маршрута: поток живёт на хосте, и подписаться
	 * на него из страницы нельзя. Опрос идёт четыре раза в секунду — этого хватает
	 * для живого индикатора и незаметно для сети.
	 */
	class Recording {
	  constructor() {
	    this.phase = 'idle'
	    this.startedAt = 0
	    this.maxSeconds = MAX_RECORD_SECONDS
	    this.onLevel = null
	    this.onFailure = null
	    this.levelTimer = 0
	    this.disposed = false
	    this.seconds = 0
	  }

	  /**
	   * Просит хост начать запись и включает опрос уровня.
	   *
	   * @param {object} options - параметры.
	   * @param {(kind: string, message: string) => void} [options.onFailure] - обработчик обрыва.
	   * @param {(level: number) => void} [options.onLevel] - уровень сигнала 0..1.
	   */
	  async start({ onFailure, onLevel } = {}) {
	    this.onLevel = typeof onLevel === 'function' ? onLevel : null
	    this.onFailure = typeof onFailure === 'function' ? onFailure : null

	    const support = probeSupport()
	    if (!support.available) {
	      throw new RecorderError('unsupported', 'Хост недоступен — плагин работает только в DSH.')
	    }

	    const answer = await startRecording()
	    if (this.disposed) {
	      // Компонент разобрали, пока шёл запрос: запись надо погасить, иначе
	      // микрофон останется открытым после выгрузки плагина.
	      void cancelRecording()
	      return
	    }
	    if (answer.ok !== true) throw classifyFailure(answer)

	    this.phase = 'recording'
	    this.startedAt = Date.now()
	    if (typeof answer.value?.maxSeconds === 'number') this.maxSeconds = answer.value.maxSeconds
	    this.levelTimer = setInterval(() => { void this.poll() }, 250)
	  }

	  /**
	   * Один опрос состояния: обновляет уровень и ловит обрыв записи на хосте.
	   *
	   * @returns {Promise<void>}
	 */
	  async poll() {
	    if (this.phase !== 'recording') return
	    const answer = await recordingStatus()
	    if (this.disposed) return
	    if (answer.ok !== true) return
	    const state = answer.value
	    if (state?.recording !== true) {
	      // Хост закончил запись сам — например, упёрся в лимит времени. Молчать
	      // тут нельзя: пользователь смотрел бы на «идёт запись» вечно.
	      this.phase = 'ended'
	      this.clearTimer()
	      this.onFailure?.('ended', '')
	      return
	    }
	    this.seconds = state.seconds ?? 0
	    this.onLevel?.(state.level ?? 0)
	  }

	  /**
	   * Останавливает запись и отдаёт готовое аудио.
	   *
	   * Base64 не декодируется и не перекодируется: хост уже отдал WAV в base64,
	   * ровно в том виде, в каком его принимает маршрат распознавания. Обратное
	   * преобразование здесь было бы лишним копированием мегабайта данных.
	   *
	   * @returns {Promise<{ audioBase64: string, bytes: number }>} аудио для распознавания.
	   */
	  async stop() {
	    if (this.phase === 'stopped') throw new RecorderError('not-recording', 'Запись уже остановлена')
	    this.clearTimer()
	    const answer = await stopRecording()
	    if (answer.ok !== true) throw classifyFailure(answer)
	    this.phase = 'stopped'
	    if (typeof answer.value?.audioBase64 !== 'string') {
	      throw new RecorderError('lost', 'Хост вернул запись без данных.')
	    }
	    return {
	      audioBase64: answer.value.audioBase64,
	      bytes: answer.value.bytes ?? 0,
	    }
	  }

	  /** Останавливает таймер опроса, если он идёт. */
	  clearTimer() {
	    if (this.levelTimer !== 0) {
	      clearInterval(this.levelTimer)
	      this.levelTimer = 0
	    }
	  }

	  /**
	   * Гасит запись: снимает таймер и просит хост прекратить писать.
	   *
	   * Идемпотентно — к нему обращаются и отмена, и выгрузка плагина.
	   *
	   * @returns {void}
	   */
	  dispose() {
	    if (this.disposed) return
	    this.disposed = true
	    this.clearTimer()
	    if (this.phase === 'recording') void cancelRecording()
	    this.phase = 'idle'
	  }
	}

	/**
	 * Перечисляет микрофоны.
	 *
	 * Функция сохранена ради прежнего контракта: UI больше её не зовёт — захват
	 * идёт на хосте и устройство выбирает он, — но плагины, встроившие чужой код
	 * с этим импортом, продолжат собираться.
	 *
	 * @returns {Promise<string[]>} всегда пустой список.
	 */
	async function listMicrophones() {
	  return []
	}

	// ── src/client/settingsPanel.js ─────────────────────────────────
	// Настройки голосового ввода: страница в общих настройках приложения.
	//
	// Почему не пункт в левой колонке. Пункт панели и панель `main` — неразлучная
	// пара, а отсутствие половины роняет приложение: `layout.selectPanel` бросает
	// для незарегистрированной панели («main panel … is not registered»). Так было
	// дважды, и оба раза пришлось отключать плагин.
	//
	// Настройки живут там, где им место по устройству интерфейса: `settings.section`
	// — целая страница (так же сделана страница пресетов агента), а
	// `settings.general.item` — переключатели прямо в общем разделе. Это те же
	// штатные слоты, куда пишут locale и тема оформления, и их риск уже измерили
	// другие плагины.


	/** Идентификатор страницы настроек. */
	const SECTION_ID = 'voice-eternia'

	/**
	 * Идентификатор пункта в левой панели и ключ его панели.
	 */
	const PANEL_ID = 'voice-eternia-panel'

	/**
	 * Порядок пункта в левой панели.
	 *
	 * Ниже штатных панелей: настройки плагина не должны вытеснять то, чем человек
	 * пользуется каждый день.
	 */
	const PANEL_ORDER = 50

	/**
	 * Порядок страницы среди прочих.
	 *
	 * Число ниже штатных разделов: настройки плагина не должны вытеснять то, чем
	 * человек пользуется каждый день.
	 */
	const SECTION_ORDER = 30

	/**
	 * Поля формы: группа, ключ, подпись, тип, подсказка.
	 *
	 * Подсказка обязательна у каждого поля. Без неё настройка превращается в
	 * загадку: «Insertion target: cursor» ничего не говорит о том, что бывают ещё
	 * `captured` и `replace`, а «Leave @file chips alone» — о том, какие именно
	 * @файлы и почему их лучше не трогать. Человек не должен угадывать смысл
	 * собственных настроек.
	 *
	 * Тип `model` рисует выпадающий список БЕСПЛАТНЫХ моделей, настроенных в самом
	 * DSH: `id` провайдера и точное имя модели человек помнить не обязан, а платные
	 * здесь не предлагаются — диктовка и полировка не та задача, ради которой стоит
	 * платить. Поле остаётся редактируемым: модель без суффикса `:free` или свой
	 * шлюз в списке не появятся, а запрещать их — значит запрещать работать.
	 *
	 * Модели полировки в списке полей НЕТ намеренно. Полирует текст та же модель,
	 * на которой идёт разговор: держать вторую настройку ради того же действия —
	 * лишний выбор, который ничего не решает, зато требует внимания.
	 */
	const FIELDS = [
	  // Провайдер — ИМЯ записи с ключом, а не ключ. Список, а не текстовое поле:
	  // в поле «провайдер» люди вставляли сам ключ, и он оставался на экране
	  // открытым текстом. Значения для списка приходят с хоста (имена записей из
	  // хранилища ключей), вписать секрет сюда физически некуда.
	  { group: 'asr', key: 'provider', label: 'settings.provider', type: 'credential', hint: 'settings.hintProvider' },
	  { group: 'asr', key: 'model', label: 'settings.asrModel', type: 'model', hint: 'settings.hintAsrModel' },
	  { group: 'asr', key: 'baseUrl', label: 'settings.baseUrl', type: 'text', hint: 'settings.hintBaseUrl' },
	  { group: 'asr', key: 'language', label: 'settings.language', type: 'text', hint: 'settings.hintLanguage' },
	  { group: 'polish', key: 'enabled', label: 'settings.polishOn', type: 'bool', hint: 'settings.hintPolishOn' },
	  { group: 'polish', key: 'preset', label: 'settings.preset', type: 'preset', hint: 'settings.hintPreset' },
	  { group: 'polish', key: 'prompt', label: 'settings.prompt', type: 'area', hint: 'settings.hintPrompt' },
	  { group: 'polish', key: 'temperature', label: 'settings.temperature', type: 'number', hint: 'settings.hintTemperature' },
	  { group: 'recording', key: 'device', label: 'settings.device', type: 'text', hint: 'settings.hintDevice' },
	  { group: 'recording', key: 'maxSeconds', label: 'settings.maxSeconds', type: 'number', hint: 'settings.hintMaxSeconds' },
	  { group: 'recording', key: 'inputGain', label: 'settings.inputGain', type: 'number', hint: 'settings.hintInputGain' },
	  { group: 'recording', key: 'noiseSuppress', label: 'settings.noise', type: 'bool', hint: 'settings.hintNoise' },
	  { group: 'insert', key: 'mode', label: 'settings.insertMode', type: 'select', hint: 'settings.hintInsertMode', options: ['cursor', 'captured', 'replace'] },
	  { group: 'insert', key: 'preserveChips', label: 'settings.preserveChips', type: 'bool', hint: 'settings.hintPreserveChips' },
	  { group: 'ui', key: 'showBrowserFallback', label: 'settings.browser', type: 'bool', hint: 'settings.hintBrowser' },
	  { group: 'ui', key: 'confirmOnInsert', label: 'settings.confirm', type: 'bool', hint: 'settings.hintConfirm' },
	]

	/**
	 * Готовые промпты полировки.
	 *
	 * Смысл набора: у диктовки нет одного «правильного» стиля. Наговорённое на
	 * встрече, письмо коллеге и техническая заметка требуют разной обработки, и
	 * заставлять человека писать инструкцию редактору с нуля — значит требовать
	 * знания промпт-инженерии там, где достаточно выбрать задачу.
	 *
	 * Текст инструкции здесь НЕ хранится, только ключ словаря: русская строка в
	 * коде показывалась бы и в английском интерфейсе, и человек получал бы русскую
	 * инструкцию редактору при английском окне.
	 *
	 * `id` попадает в настройки как `polish.preset`. Пустой `id` означает «своя
	 * инструкция»: текст поля не подменяется.
	 */
	const PRESETS = [
	  { id: '', label: 'settings.presetCustom' },
	  { id: 'plain', label: 'settings.presetPlain', prompt: 'settings.prompt.plain' },
	  { id: 'business', label: 'settings.presetBusiness', prompt: 'settings.prompt.business' },
	  { id: 'note', label: 'settings.presetNote', prompt: 'settings.prompt.note' },
	  { id: 'meeting', label: 'settings.presetMeeting', prompt: 'settings.prompt.meeting' },
	  { id: 'code', label: 'settings.presetCode', prompt: 'settings.prompt.code' },
	  { id: 'message', label: 'settings.presetMessage', prompt: 'settings.prompt.message' },
	  { id: 'clean', label: 'settings.presetClean', prompt: 'settings.prompt.clean' },
	]

	/** Группы и их заголовки. */
	const GROUPS = [
	  { id: 'asr', title: 'settings.groupAsr' },
	  { id: 'polish', title: 'settings.groupPolish' },
	  { id: 'recording', title: 'settings.groupRecording' },
	  { id: 'insert', title: 'settings.groupInsert' },
	  { id: 'ui', title: 'settings.groupUi' },
	]

	/**
	 * Копирует настройки глубоко.
	 *
	 * Форма правит вложенные группы по месту, и общий снимок из хоста трогать нельзя:
	 * он общий с подпиской, и правка на месте обнулила бы её у всех.
	 *
	 * @param {object} source - исходные настройки.
	 * @returns {object} независимая копия.
	 */
	function cloneSettings(source) {
	  const result = {}
	  for (const group of Object.keys(source ?? {})) {
	    result[group] = { ...source[group] }
	  }
	  return result
	}

	/**
	 * Значение поля из снимка настроек.
	 *
	 * @param {object} settings - настройки.
	 * @param {string} id - путь «группа.ключ».
	 * @returns {*} значение.
	 */
	function valueAt(settings, id) {
	  const [group, key] = id.split('.')
	  return settings?.[group]?.[key]
	}

	/**
	 * Переводит ключ, не выбрасывая его при неудаче.
	 *
	 * Сырой ключ в интерфейсе недопустим, но и пустая строка ничего не объяснит —
	 * ключ хотя бы говорит, чего не хватило.
	 *
	 * @param {Function} t - переводчик.
	 * @param {string} key - ключ словаря.
	 * @returns {string} подпись.
	 */
	function label(t, key) {
	  try {
	    const value = t(key)
	    return typeof value === 'string' && value !== '' ? value : key
	  } catch {
	    return key
	  }
	}

	/**
	 * Рисует поле нужного типа.
	 *
	 * @param {object} spec - описание поля.
	 * @param {*} value - текущее значение.
	 * @param {(raw: *) => void} onChange - обработчик правки.
	 * @param {Function} t - переводчик.
	 * @returns {object} элемент React.
	 */
	function renderInput(spec, value, onChange, t) {
	  const React = require('react')
	  const common = {
	    id: `vet-${spec.group}-${spec.key}`,
	    'aria-label': label(t, spec.label),
	    value: value === undefined || value === null ? '' : String(value),
	    onChange: (event) => onChange(event.target.value),
	  }
	  if (spec.type === 'bool') {
	    return React.createElement('input', {
	      type: 'checkbox',
	      checked: value === true,
	      'aria-label': label(t, spec.label),
	      onChange: (event) => onChange(event.target.checked),
	    })
	  }
	  if (spec.type === 'area') {
	    return React.createElement('textarea', Object.assign({}, common, {
	      rows: 4,
	      placeholder: label(t, 'settings.promptPlaceholder'),
	    }))
	  }
	  if (spec.type === 'credential') {
	    // Список имён записей с ключами. Показаны только имена: сами ключи остаются
	    // на хосте и в интерфейс не попадают — ни в списке, ни в значении поля.
	    const credentials = Array.isArray(spec.credentials) ? spec.credentials : []
	    const current = value === undefined || value === null ? '' : String(value)
	    const known = credentials.some((item) => item.provider === current)
	    return React.createElement('span', { className: 'vet-page__model' },
	      React.createElement('select', {
	        className: 'vet-page__select',
	        'aria-label': label(t, spec.label),
	        value: known ? current : '',
	        onChange: (event) => onChange(event.target.value),
	      },
	      React.createElement('option', { value: '' },
	        known ? current : label(t, 'settings.credentialPick')),
	      credentials.map((item) => React.createElement('option', { key: item.provider, value: item.provider },
	        item.keyName === '' ? item.provider : `${item.provider} — ${item.keyName}`,
	      )),
	      ),
	    )
	  }
	  if (spec.type === 'select') {
	    // Строгий выбор из перечисленного: свободный ввод здесь означал бы
	    // настройку, которую хост молча отбросит при проверке значения.
	    const options = Array.isArray(spec.options) ? spec.options : []
	    const current = value === undefined || value === null ? '' : String(value)
	    return React.createElement('select', {
	      className: 'vet-page__select',
	      'aria-label': label(t, spec.label),
	      value: options.includes(current) ? current : (options[0] ?? ''),
	      onChange: (event) => onChange(event.target.value),
	    }, options.map((option) => React.createElement('option', { key: option, value: option },
	      label(t, `settings.option.${option}`),
	    )))
	  }
	  if (spec.type === 'preset') {
	    // Выбор задачи. Текст инструкции подставляется в поле ниже, поэтому набор
	    // не запирает человека: выбрав «своя», он пишет что угодно.
	    const current = value === undefined || value === null ? '' : String(value)
	    return React.createElement('span', { className: 'vet-page__model' },
	      React.createElement('select', {
	        className: 'vet-page__select',
	        'aria-label': label(t, spec.label),
	        value: current,
	        onChange: (event) => onChange(event.target.value),
	      }, PRESETS.map((preset) => React.createElement('option', { key: preset.id, value: preset.id },
	        label(t, preset.label),
	      ))),
	      React.createElement('span', { className: 'vet-page__hint' }, label(t, 'settings.presetNote')),
	    )
	  }
	  if (spec.type === 'model') {
	    // Выпадающий список моделей DSH плюс своя строка ввода.
	    //
	    // Список берётся из профиля, поэтому здесь оказываются именно те модели,
	    // что человек видит в разделе «Модели», и бесплатные идут первыми. Свободный
	    // ввод сохранён: модель без суффикса `:free` или свой шлюз в списке не
	    // появятся, а запрещать их — значит запрещать работать.
	    const models = Array.isArray(spec.models) ? spec.models : []
	    const current = value === undefined || value === null ? '' : String(value)
	    const known = models.some((item) => item.id === current)
	    return React.createElement('span', { className: 'vet-page__model' },
	      React.createElement('select', {
	        className: 'vet-page__select',
	        'aria-label': label(t, spec.label),
	        value: known ? current : '',
	        onChange: (event) => {
	          // Пустой пункт — «своё значение»: он не должен затирать уже
	          // вписанную модель, иначе выбор исчезнет на полпути.
	          if (event.target.value === '') return
	          onChange(event.target.value)
	        },
	      },
	      React.createElement('option', { value: '' },
	        known ? label(t, 'settings.modelCustom') : (current === '' ? label(t, 'settings.modelPick') : current)),
	      models.map((item) => React.createElement('option', { key: `${item.provider}/${item.id}`, value: item.id },
	        item.free ? `${item.name} — ${label(t, 'settings.free')}` : item.name,
	      )),
	      ),
	      React.createElement('input', Object.assign({}, common, { type: 'text', className: 'vet-page__modelText' })),
	    )
	  }
	  return React.createElement('input', Object.assign({}, common, {
	    type: spec.type === 'number' ? 'number' : 'text',
	  }))
	}

	/**
	 * Страница настроек голосового ввода.
	 *
	 * @param {object} props - свойства ячейки.
	 * @returns {object} элемент React.
	 */
	function SettingsSection({ t: translate = (key) => key }) {
	  const React = require('react')
	  const [draft, setDraft] = React.useState(null)
	  const [busy, setBusy] = React.useState(true)
	  const [saving, setSaving] = React.useState(false)
	  const [error, setError] = React.useState('')
	  const [saved, setSaved] = React.useState(false)
	  const [models, setModels] = React.useState([])
	  const [credentials, setCredentials] = React.useState([])

	  // Перевод нужен внутри обработчика выбора задачи, а он переживает смену языка:
	  // держим свежую ссылку, чтобы подставленная инструкция всегда была на том
	  // языке, что виден в окне.
	  const translateRef = React.useRef(translate)
	  translateRef.current = typeof translate === 'function' ? translate : defaultTranslate

	  React.useEffect(() => {
	    let alive = true
	    void readConfig().then((config) => {
	      if (!alive) return
	      setDraft(config === null ? {} : cloneSettings(config))
	      setBusy(false)
	    })
	    // Модели грузятся отдельно: их отсутствие не должно мешать править
	    // остальные настройки, поэтому неудача здесь просто оставляет список пустым,
	    // а поля работают как обычные строки ввода.
	    void readModels().then((list) => {
	      if (!alive || list === null) return
	      setModels(list)
	    })
	    // Имена записей с ключами: сами ключи остаются на хосте.
	    void readCredentials().then((list) => {
	      if (!alive || list === null) return
	      setCredentials(list)
	    })
	    return () => { alive = false }
	  }, [])

	  const set = (id, raw) => {
	    const spec = FIELDS.find((item) => `${item.group}.${item.key}` === id)
	    if (spec === undefined) return
	    setSaved(false)
	    setDraft((current) => {
	      const next = cloneSettings(current ?? {})
	      next[spec.group] = next[spec.group] ?? {}
	      // Тип приводится здесь, а не на хосте: текстовое поле для числа должно
	      // отдать хосту число, иначе настройка молча отбросится при проверке типа.
	      let value = raw
	      if (spec.type === 'bool') value = raw === true
	      else if (spec.type === 'number') value = Number(raw)
	      else value = String(raw)
	      next[spec.group][spec.key] = value
	      // Выбор задачи подставляет её инструкцию в поле промпта: человек выбирает
	      // «Протокол встречи» и сразу видит, что именно уйдёт редактору, — а не
	      // получает текстовое поле без объяснений.
	      if (spec.type === 'preset') {
	        const preset = PRESETS.find((item) => item.id === value)
	        // Текст берётся переводом: в поле должен лежать тот же язык, что и в окне.
	        if (preset !== undefined && typeof preset.prompt === 'string' && preset.prompt !== '') {
	          // Именно .current: label() зовёт переданное как функцию, а сам ref —
	          // это объект, и вызов на нём бросает TypeError. Ошибка тихая: label()
	          // ловит её и возвращает ключ, поэтому в поле попадал settings.prompt.*
	          // вместо текста инструкции.
	          next.polish.prompt = label(translateRef.current, preset.prompt)
	        }
	      }
	      return next
	    })
	  }

	  const save = async () => {
	    setSaving(true)
	    setError('')
	    const answer = await writeConfig(draft ?? {})
	    setSaving(false)
	    if (answer.ok !== true) {
	      setError(typeof answer.error?.message === 'string'
	        ? answer.error.message
	        : label(translate, 'settings.saveFailed'))
	      return
	    }
	    // Подтверждение нужно: значения сохранены, и форма обязана это показать —
	    // иначе человек гадает, сработало ли.
	    setSaved(true)
	  }

	  if (busy === true || draft === null) {
	    return React.createElement('p', { className: 'vet-page__note' }, label(translate, 'settings.loading'))
	  }

	  return React.createElement('div', { className: 'vet-page' },
	    React.createElement('header', { className: 'vet-page__head' },
	      React.createElement('h2', { className: 'vet-page__title' }, label(translate, 'settings.title')),
	    ),
	    // Группы завёрнуты в общий контейнер: он раскладывает их двумя колонками,
	    // а заголовок и кнопка сохранения остаются во всю ширину.
	    React.createElement('div', { className: 'vet-page__groups' },
	      ...GROUPS.map((group) => React.createElement('section', { className: 'vet-page__group', key: group.id },
	        React.createElement('h3', { className: 'vet-page__groupTitle' }, label(translate, group.title)),
	        ...FIELDS.filter((item) => item.group === group.id).map((item) => {
	          const id = `${item.group}.${item.key}`
	          // Модели подставляются только в поля-списки: текстовые поля от них
	          // не зависят и лишний пропс им ни к чему.
	          let spec = item
	        if (item.type === 'model') spec = Object.assign({}, item, { models })
	        if (item.type === 'credential') spec = Object.assign({}, item, { credentials })
	          return React.createElement('label', { className: 'vet-page__field', key: id },
	            React.createElement('span', { className: 'vet-page__label' }, label(translate, item.label)),
	            renderInput(spec, valueAt(draft, id), (raw) => set(id, raw), translate),
	            // Подсказка под полем, а не всплывающая: настройку читают один раз, и
	            // объяснение должно быть на виду, а не ждать наведения мышью.
	            React.createElement('span', { className: 'vet-page__hint' }, label(translate, item.hint)),
	          )
	        }),
	      )),
	    ),
	    error === ''
	      ? null
	      : React.createElement('p', { className: 'vet-page__error', role: 'alert' }, error),
	    saved === true
	      ? React.createElement('p', { className: 'vet-page__saved', role: 'status' }, label(translate, 'settings.saved'))
	      : null,
	    React.createElement('div', { className: 'vet-page__foot' },
	      React.createElement('button', {
	        type: 'button',
	        className: 'vet-page__save',
	        'data-primary': 'true',
	        disabled: saving === true,
	        onClick: () => { void save() },
	      }, label(translate, 'settings.save')),
	    ),
	  )
	}

	/**
	 * Иконка пункта в левой панели.
	 *
	 * Только значок: слот рендерится как `renderSlot('sidebar.panellist',
	 * { size, active })`, а кнопку вокруг рисует сама панель — её обработчик
	 * вызывает `layout.selectPanel(id)`. Своя кнопка внутри чужой перехватила бы
	 * клик, и настройки просто не открылись бы.
	 *
	 * @returns {object} элемент React.
	 */
	function PanelIcon() {
	  const React = require('react')
	  return React.createElement('svg', {
	    width: '1em',
	    height: '1em',
	    viewBox: '0 0 24 24',
	    fill: 'none',
	    stroke: 'currentColor',
	    strokeWidth: 1.8,
	    'aria-hidden': 'true',
	  }, React.createElement('circle', { cx: 12, cy: 12, r: 3.2 }),
	  React.createElement('path', {
	    d: 'M12 2.8v2.6M12 18.6v2.6M21.2 12h-2.6M5.4 12H2.8M18.5 5.5l-1.8 1.8M7.3 16.7l-1.8 1.8M18.5 18.5l-1.8-1.8M7.3 7.3 5.5 5.5',
	  }))
	}


	// ── src/client/dictate.js ───────────────────────────────────────
	// Кнопка микрофона: диктовка на панели ввода.
	//
	// Место в слоте `conversation.input.right` — список компактных контролов перед
	// кнопкой отправки. Свой `id` обязателен: слот листовой, и повтор чужого id
